import{_ as t,o,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年9月4日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-04.md","filePath":"science-log/src/reconstructed/2026-09-04.md"}'),e={name:"science-log/src/reconstructed/2026-09-04.md"};function g(a,r,i,c,l,p){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年9月4日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月4日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月4日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月4日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-04 为<strong>周五</strong>。CrossRef 精确当日命中：Nature（0028-0836）<strong>8 条全部为 <code>d41586-…</code> 新闻/Briefing，无研究论文</strong>；PNAS（0027-8424）<strong>11 条研究论文</strong>；Science 系（10.1126）<strong>98 条</strong>（含 Science Advances / Science Immunology 研究论文）。故科学 5 篇全部取自<strong>当日真实命中</strong>（PNAS + Science Advances），优先方法新颖、结论具体者。<strong>AI 5 篇</strong>为当日 arXiv cs.AI 提交（submittedDate <code>[202609040000 TO 202609042359]</code>，取前 30 条中遴选）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧠-失聪者大脑把视觉资源-搬-到周边视野-v1-与丘脑的视网膜拓扑重映射" tabindex="-1">🧠 失聪者大脑把视觉资源&quot;搬&quot;到周边视野：V1 与丘脑的视网膜拓扑重映射 <a class="header-anchor" href="#🧠-失聪者大脑把视觉资源-搬-到周边视野-v1-与丘脑的视网膜拓扑重映射" aria-label="Permalink to &quot;🧠 失聪者大脑把视觉资源&quot;搬&quot;到周边视野：V1 与丘脑的视网膜拓扑重映射&quot;">​</a></h3><p><strong>Retinotopic remapping of the visual system in deaf adults</strong><em>PNAS（2026）</em></p><p>早期深度失聪者常表现出更强的周边视觉敏感度，但这种优势是否反映了<strong>早期视觉脑结构的改变</strong>一直缺少直接证据。英国约克大学 Alexandra T. Levine、Alex R. Wade 团队用<strong>功能磁共振（fMRI）<strong>对 <strong>16 名早发深度失聪成人</strong>与 <strong>16 名年龄匹配的听力对照</strong>做</strong>视野映射</strong>，结果发现失聪组在<strong>初级视皮层（V1）<strong>与</strong>丘脑外侧膝状体（LGN）<strong>中，<strong>远周边视野的皮层表征都更大</strong>。关键区分在于：这</strong>并非</strong>视觉地图整体扩张——两结构的总体积两组无差异——而是<strong>中央视野表征变小</strong>，即神经资源发生了<strong>再分配（redistribution）</strong>。这说明感觉剥夺不是&quot;留白&quot;，而是<strong>按发育期需求重新瓜分同一块皮层预算</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2532413123" target="_blank" rel="noreferrer">10.1073/pnas.2532413123</a></p><h3 id="🦎-一个氨基酸改写热感知-trpa1-单点突变让卵生胚胎耐高温" tabindex="-1">🦎 一个氨基酸改写热感知：TRPA1 单点突变让卵生胚胎耐高温 <a class="header-anchor" href="#🦎-一个氨基酸改写热感知-trpa1-单点突变让卵生胚胎耐高温" aria-label="Permalink to &quot;🦎 一个氨基酸改写热感知：TRPA1 单点突变让卵生胚胎耐高温&quot;">​</a></h3><p><strong>A single-point mutation in TRPA1 drives heat resilience in oviparous embryos</strong><em>Science Advances（2026）</em></p><p>脊椎动物温度适应的分子基础长期不明。复旦大学生命科学学院 / 中科院动物研究所等团队发现，离子通道 <strong>TRPA1</strong> 孔域的一个氨基酸改变，发生在<strong>合弓类—双孔类分化</strong>之际，<strong>重写了它的热敏感性</strong>：保留<strong>祖先残基</strong>的众多<strong>卵生脊椎动物</strong>，其 TRPA1 被热<strong>激活</strong>，从而在高温下<strong>保护胚胎发育</strong>；而哺乳动物中被选择出<strong>天门冬氨酸</strong>，则<strong>降低了热响应</strong>。功能上，在卵生胚胎中<strong>阻断热激活的 TRPA1</strong> 会<strong>损害背根神经节轴突生长、破坏髓鞘化，并导致孵化时肢体无力</strong>。机制上，TRPA1 介导的 <strong>Ca²⁺ 内流</strong>触发转录因子 <strong>SP1 入核</strong>，进而激活 <strong>CADM1 与 MDGA1</strong>。一个突变事件把<strong>离子通道演化</strong>与<strong>热胁迫下的胚胎存活</strong>直接连了起来。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aee3948" target="_blank" rel="noreferrer">10.1126/sciadv.aee3948</a></p><h3 id="💊-来那卡帕韦如何-掰碎-hiv-衣壳-两步断裂-应力—应变模型" tabindex="-1">💊 来那卡帕韦如何&quot;掰碎&quot;HIV 衣壳：两步断裂 + 应力—应变模型 <a class="header-anchor" href="#💊-来那卡帕韦如何-掰碎-hiv-衣壳-两步断裂-应力—应变模型" aria-label="Permalink to &quot;💊 来那卡帕韦如何&quot;掰碎&quot;HIV 衣壳：两步断裂 + 应力—应变模型&quot;">​</a></h3><p><strong>Lenacapavir allosterically remodels the HIV-1 capsid</strong><em>Science Advances（2026）</em></p><p>来那卡帕韦（LEN）是高效长效的 HIV-1 <strong>衣壳抑制剂</strong>，能让成熟衣壳<strong>崩解失稳</strong>，但机制一直不清。美国犹他大学 Nayara F. B. dos Santos 等证明 LEN 是 HIV-1 衣壳结构的<strong>变构调节剂</strong>，它分<strong>两步</strong>瓦解衣壳的<strong>富勒烯锥</strong>结构：先在<strong>高曲率的&quot;纬线&quot;（declinations）处破裂</strong>，随后<strong>壳体主体出现裂隙</strong>。分子层面，LEN <strong>改变了衣壳亚基间的非共价键相互作用</strong>并<strong>降低局部晶格曲率</strong>。作者提出一个<strong>应力—应变（stress-strain）模型</strong>来统一解释 LEN 如何重塑衣壳结构、进而削弱病毒复制能力——把&quot;药物—结构—功能&quot;链条补完整。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aed8384" target="_blank" rel="noreferrer">10.1126/sciadv.aed8384</a></p><h3 id="🧬-cirpin-用-圆周排列不变-的图神经网络-扫出蛋白质宇宙的拓扑近亲" tabindex="-1">🧬 CIRPIN：用&quot;圆周排列不变&quot;的图神经网络，扫出蛋白质宇宙的拓扑近亲 <a class="header-anchor" href="#🧬-cirpin-用-圆周排列不变-的图神经网络-扫出蛋白质宇宙的拓扑近亲" aria-label="Permalink to &quot;🧬 CIRPIN：用&quot;圆周排列不变&quot;的图神经网络，扫出蛋白质宇宙的拓扑近亲&quot;">​</a></h3><p><strong>Systematic discovery of circular permutations across the protein universe using CIRPIN</strong><em>PNAS（2026）</em></p><p>深度学习极大加速了蛋白结构搜索，但现有工具常漏掉<strong>由拓扑重排关联</strong>的蛋白，尤其是<strong>圆周排列（circular permutation, CP）</strong>——结构与极相似，只是<strong>端（termini）的位置不同</strong>。MIT 的 Aiden R. Kolodziej、S. Mazdak Abulnaga、Sergey Ovchinnikov 提出 <strong>CIRPIN</strong>：一个<strong>CP 不变（circular-permutation-invariant）的图神经网络</strong>，靠<strong>合成圆周排列</strong>的数据增强策略，让模型学到<strong>对 CP 不变的表示</strong>，从而在 SCOP 与 AlphaFold Cluster Representatives 库中识别结构相似蛋白。据此他们建成 <strong>CIRPIN-DB</strong>——含 <strong>1830 万对</strong>高度富集 CP 关系的蛋白对，覆盖 CATH 分类中的 <strong>845 个独特拓扑</strong>，是迄今<strong>最大最全</strong>的 CP 资源库。这等于给&quot;结构相同、写法不同&quot;的蛋白找回亲缘关系。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2605178123" target="_blank" rel="noreferrer">10.1073/pnas.2605178123</a></p><h3 id="🌊-渔业的-前置警报-产量骤降常先于种群崩溃约十年" tabindex="-1">🌊 渔业的&quot;前置警报&quot;：产量骤降常先于种群崩溃约十年 <a class="header-anchor" href="#🌊-渔业的-前置警报-产量骤降常先于种群崩溃约十年" aria-label="Permalink to &quot;🌊 渔业的&quot;前置警报&quot;：产量骤降常先于种群崩溃约十年&quot;">​</a></h3><p><strong>Abrupt declines in fish productivity often precede stock collapses in marine fisheries</strong><em>Science Advances（2026）</em></p><p>过捕与气候变暖会引发鱼类生产力<strong>大幅、突然且持续</strong>的转变，但全球尺度的评估长期缺失。法国蒙彼利埃演化科学研究所（ISEM）Mathieu Pélissié、Vasilis Dakos 等系统分类了全球<strong>机构评估渔业</strong>的<strong>种群生产力时间动态</strong>：在分析的 <strong>315 个鱼种</strong>中，<strong>超过四分之一</strong>检测到<strong>生产力突变</strong>。<strong>骤降</strong>在<strong>升温最快</strong>的海区<strong>显著过度代表</strong>，而<strong>骤增</strong>更可能出现在<strong>捕捞强度较低</strong>处。更关键的是，在发生突变的种群中，约<strong>四分之一</strong>其<strong>生产力骤降早于种群崩溃约十年</strong>。作者由此强调：把<strong>生产力突变</strong>纳入管理指标，才能降低暖化海洋中鱼类种群崩溃的风险——这是一条<strong>可操作的前置预警</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aed7911" target="_blank" rel="noreferrer">10.1126/sciadv.aed7911</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧱-把-kv-缓存塞进片内非易失存储-面向固定量程转换器的量化方案" tabindex="-1">🧱 把 KV 缓存塞进片内非易失存储：面向固定量程转换器的量化方案 <a class="header-anchor" href="#🧱-把-kv-缓存塞进片内非易失存储-面向固定量程转换器的量化方案" aria-label="Permalink to &quot;🧱 把 KV 缓存塞进片内非易失存储：面向固定量程转换器的量化方案&quot;">​</a></h3><p><strong>Interface-Aware KV Cache Quantization for Dense On-Chip NVM in Long-Context LLM Decoding</strong><em>arXiv:2609.05764（2026）</em></p><p>长上下文 LLM 解码的<strong>主导瓶颈是 KV 缓存</strong>——每一步都要<strong>整块读取</strong>，故解码<strong>受显存带宽约束</strong>。把<strong>量化后的 KV 缓存</strong>驻留在<strong>片内高密度非易失存储（NVM）<strong>里，可</strong>消除片外搬运</strong>。但现有 KV 量化方法是为<strong>类 GPU 存储体系</strong>设计的：<strong>KIVI</strong> 附带逐组元数据，让存储<strong>增加约 25%</strong>；<strong>KVQuant</strong> 保留<strong>稀疏的全精度离群值</strong>，而<strong>密集阵列无法就地存放</strong>。本文考察这些结构落在<strong>固定量程转换器之后的 NVM</strong> 上时的代价，并设计<strong>与该接口匹配</strong>的量化方案：量化 KV 存于片内密集 NVM，只用<strong>一块小型静态模拟交叉阵列做固定旋转</strong>，注意力计算留在<strong>片内数字逻辑</strong>。核心是<strong>让量化结构服从硬件接口</strong>，而非反之。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.05764" target="_blank" rel="noreferrer">2609.05764</a></p><h3 id="🛠️-不改模型也能提升工具智能体-把-运行时挽具-当资源受限的选择问题" tabindex="-1">🛠️ 不改模型也能提升工具智能体：把&quot;运行时挽具&quot;当资源受限的选择问题 <a class="header-anchor" href="#🛠️-不改模型也能提升工具智能体-把-运行时挽具-当资源受限的选择问题" aria-label="Permalink to &quot;🛠️ 不改模型也能提升工具智能体：把&quot;运行时挽具&quot;当资源受限的选择问题&quot;">​</a></h3><p><strong>Beyond Prompts: Measuring and Optimizing LLM Tool-Agent Harnesses</strong><em>arXiv:2609.05736（2026）</em></p><p>LLM 工具智能体可<strong>不重训模型</strong>、只改<strong>运行时挽具（harness）<strong>来提升——即提示、工具接口、中间件、状态处理与恢复逻辑。本文把问题形式化为</strong>固定模型多轮工具智能体的&quot;资源受限挽具选择&quot;</strong>，把搜索面限定在<strong>提示 + 工具边界中间件</strong>：编辑是<strong>工具边界上的受保护拦截</strong>，而<strong>不是任意改写智能体执行逻辑</strong>。作者提出<strong>优化器无关</strong>的评测协议，报告<strong>平均留出增益、最差条件增益、可重复性、成本诊断</strong>，以及 <strong>RelLift95(B)</strong>——对给定预算 B 下所选挽具留出增益的<strong>保守估计</strong>。并以 <strong>PRISM</strong>（聚类失败、把修复路由到提示 / 工具边界中间件 / 联合编辑面）等优化器实例化。这是把&quot;智能体调优&quot;从玄学推向<strong>可复现、带预算与置信下界</strong>的工程学。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.05736" target="_blank" rel="noreferrer">2609.05736</a></p><h3 id="📚-谁来维护智能体技能-人类主导、ai-辅助的纵向研究" tabindex="-1">📚 谁来维护智能体技能？人类主导、AI 辅助的纵向研究 <a class="header-anchor" href="#📚-谁来维护智能体技能-人类主导、ai-辅助的纵向研究" aria-label="Permalink to &quot;📚 谁来维护智能体技能？人类主导、AI 辅助的纵向研究&quot;">​</a></h3><p><strong>Who Maintains Agent Skills? A Longitudinal Study of Human-Governed, AI-Assisted Skill Maintenance</strong><em>arXiv:2609.05677（2026）</em></p><p>终身学习的 LLM 智能体越来越依赖<strong>外部技能制品</strong>（通常是可移植的 Markdown 文件如 <strong>SKILL.md</strong>）来保存与复用能力，它们必须随工具与用法变化被<strong>修正、扩充与整合</strong>。近期工作试图<strong>自动化技能策展</strong>，但多以<strong>自动基线</strong>评估，<strong>把人类维护当作未测量的瓶颈</strong>。本文直接研究这一缺失环节：挖掘 <strong>5 个公开 AI 技能仓库</strong>的<strong>完整提交历史</strong>（覆盖 <strong>873 次提交、143 个技能文件、254 次实质性创建后编辑</strong>，时间跨 2025-10 至 2026-06），用<strong>预注册</strong>的治理 / 操作 / 触发证据编码簿逐条编码。结论直指一个被忽视的事实：<strong>技能维护的人—机分工才是关键变量</strong>，纯自动策展的评估高估了自动化程度。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.05677" target="_blank" rel="noreferrer">2609.05677</a></p><h3 id="⚠️-ai-开发中的-偏差正常化-组织为何先天倾向漂向失败" tabindex="-1">⚠️ AI 开发中的&quot;偏差正常化&quot;：组织为何先天倾向漂向失败 <a class="header-anchor" href="#⚠️-ai-开发中的-偏差正常化-组织为何先天倾向漂向失败" aria-label="Permalink to &quot;⚠️ AI 开发中的&quot;偏差正常化&quot;：组织为何先天倾向漂向失败&quot;">​</a></h3><p><strong>The Normalization of Deviance in AI Development</strong><em>arXiv:2609.05749（2026）</em></p><p>AI 风险研究<strong>压倒性地聚焦&quot;能力风险&quot;</strong>——系统过强、过自主或与人类价值错位；对<strong>组织层面</strong>的关注则少得多：建造这些系统的机构<strong>是否本身就容易漂向失败</strong>？本文主张<strong>答案是肯定的</strong>。无论 AI 系统多么强大，建造它们的组织都面临<strong>与过往重大技术灾难相同的结构性动力学</strong>。作者以<strong>挑战者号航天飞机、三里岛事故、波音 737 MAX 空难</strong>为案例，识别每次失败前的<strong>共性结构机制</strong>（即可疑偏差被逐步接受为常态），并将其<strong>映射到当代 AI 开发</strong>。结论：<strong>现有安全基础设施提供的保护可能比表面看起来更少</strong>——这把 AI 安全从&quot;模型属性&quot;扩展到<strong>组织社会学</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.05749" target="_blank" rel="noreferrer">2609.05749</a></p><h3 id="🏢-di-bench-为-企业智能体-自动生成领域数据智能基准" tabindex="-1">🏢 DI-Bench：为&quot;企业智能体&quot;自动生成领域数据智能基准 <a class="header-anchor" href="#🏢-di-bench-为-企业智能体-自动生成领域数据智能基准" aria-label="Permalink to &quot;🏢 DI-Bench：为&quot;企业智能体&quot;自动生成领域数据智能基准&quot;">​</a></h3><p><strong>DI-Bench: Systematically Generating In-Domain Data Intelligence Benchmarks for Enterprise Agents</strong><em>arXiv:2609.05776（2026）</em></p><p>评测企业智能体需要<strong>领域专用基准</strong>，但公开基准很少检验智能体能否<strong>把业务知识与解析计算结合起来</strong>，而人工构造这类基准又<strong>极其昂贵</strong>。本文提出 <strong>DI-Bench</strong>——一条为<strong>数据智能（data intelligence, DI）<strong>生成</strong>真实基准</strong>的流水线，DI 即<strong>从海量企业数据中提取洞察</strong>的实践。为逼近需要<strong>计算 + 知识检索</strong>的真实 DI 任务，DI-Bench 在<strong>数据表、维度、指标与文档</strong>之上构建<strong>制品链接图（artifact linkage graph）</strong>，据此生成<strong>同时涉及结构化数据与相关知识</strong>的问题；标准答案经<strong>查询执行</strong>导出，再由 <strong>LLM 生成并验证</strong>题目。在两个公开数据集上，该流水线产出一个 <strong>731 题</strong>的基准，覆盖知识检索、解析计算等维度。核心贡献是把&quot;企业级评测&quot;从手工作坊变成<strong>可规模化生成的流水线</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.05776" target="_blank" rel="noreferrer">2609.05776</a></p><blockquote><p>📅 日期：2026-09-04 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const h=t(e,[["render",g]]);export{d as __pageData,h as default};
